'use strict';
const GC_MIX_GROUPS={alcohols:{name:'Alcohols · similar polar, protic character',ids:['methanol','ethanol','isopropanol','propanol'],column:'wax',diluent:'water'},hydrocarbons:{name:'Alkanes / cycloalkane · nonpolar',ids:['hexane','cyclohexane','heptane','octane','decane'],column:'pdms',diluent:'dichloromethane'},aromatics:{name:'Alkyl aromatics · low polarity',ids:['toluene','ethylbenzene'],column:'phenyl',diluent:'hexane'}};
// Approximate liquid densities at room temperature (g/mL); preparation assumes additive aliquot volumes.
const GC_MIX_DENSITY={methanol:.792,ethanol:.789,isopropanol:.785,propanol:.803,hexane:.659,cyclohexane:.779,heptane:.684,octane:.703,decane:.730,toluene:.867,ethylbenzene:.867};
const gmx={tab:'standards',group:'alcohols',mode:'neat',final:10,diluent:'water',column:'wax',label:'',amounts:{},selected:['methanol','ethanol','isopropanol','propanol'],prediction:null,message:'Mix two or more analytical solvents from one polarity family, dilute and export the same vial to GC.'};
for(const group of Object.values(GC_MIX_GROUPS))for(const id of group.ids)gmx.amounts[id]={stock:2,aliquot:1,neat:5};
try{const s=JSON.parse(localStorage.getItem('simlab-gc-mixture-draft')||'null');if(s&&GC_MIX_GROUPS[s.group])Object.assign(gmx,s,{prediction:null});}catch{}
function gcMixtureSave(){try{localStorage.setItem('simlab-gc-mixture-draft',JSON.stringify({...gmx,prediction:null}))}catch{}}
function gcMixtureTabs(){return `<div class="gc-bench-tabs" role="tablist" aria-label="GC preparation type"><button role="tab" aria-selected="${gmx.tab==='standards'}" class="btn ${gmx.tab==='standards'?'':'secondary'}" data-gmx-tab="standards">Standards &amp; unknowns</button><button role="tab" aria-selected="${gmx.tab==='mixtures'}" class="btn ${gmx.tab==='mixtures'?'':'secondary'}" data-gmx-tab="mixtures">Solvent separation mixtures</button></div>`}
function gcMixtureRecipe(){const group=GC_MIX_GROUPS[gmx.group],ids=gmx.selected;if(ids.length<2||ids.length>6)throw Error('Select at least two solvents from the same family.');if(new Set(ids).size!==ids.length||ids.some(id=>!group.ids.includes(id)))throw Error('All selected analytical solvents must belong to the selected polarity family.');if(!Number.isFinite(gmx.final)||gmx.final<=0||gmx.final>1000)throw Error('Use a positive final volume up to 1000 mL.');if(!GC_SOLVENTS.some(s=>s.id===gmx.diluent)||ids.includes(gmx.diluent))throw Error('Choose a separate diluent that is not one of the analytical solvents.');if(gmx.group==='alcohols'&&!['water','acetone','acetonitrile'].includes(gmx.diluent)||gmx.group!=='alcohols'&&!['dichloromethane','hexane','heptane','toluene','ethylAcetate','cyclohexane','acetone'].includes(gmx.diluent))throw Error('Choose a compatible diluent for the selected family.');let total=0;const mix={},preparations=[];for(const id of ids){const a=gmx.amounts[id];if(!a)throw Error('Enter an amount for every selected solvent.');let volume,mg;if(gmx.mode==='neat'){if(!Number.isFinite(a.neat)||a.neat<=0)throw Error('Neat solvent additions must be positive µL values.');volume=a.neat/1000;mg=a.neat*GC_MIX_DENSITY[id];}else if(gmx.mode==='stock'){if(!Number.isFinite(a.stock)||a.stock<=0||!Number.isFinite(a.aliquot)||a.aliquot<=0)throw Error('Stock concentrations and aliquots must be positive.');volume=a.aliquot;mg=a.stock*a.aliquot;}else throw Error('Choose neat-liquid or stock-solution preparation.');total+=volume;const concentration=mg/gmx.final;if(!(concentration>0&&concentration<=20))throw Error('Dilute each analytical component to 20 mg/mL or less; large solvent loads overload the teaching model.');mix[id]=concentration;preparations.push({id,volume_mL:volume,mass_mg:mg,concentration,density:gmx.mode==='neat'?GC_MIX_DENSITY[id]:null,stock:gmx.mode==='stock'?a.stock:null});}if(total>gmx.final+1e-9)throw Error('Combined aliquot volumes cannot exceed the final volume.');return {mix,total,preparations}}
function gcMixturePrepare(){const r=gcMixtureRecipe();if(gcal.vials.length>=30)throw Error('The vial rack holds 30 vials. Start a new calibration to clear the rack.');const v={id:gcal.next++,role:'mixture',label:String(gmx.label||GC_MIX_GROUPS[gmx.group].name.split(' · ')[0]+' mixture').slice(0,60),solvent:gmx.diluent,group:gmx.group,mix:{...r.mix},concentration:0,isC:0,preparation:{kind:'solvent-mixture',mode:gmx.mode,final:gmx.final,totalAliquot:r.total,components:r.preparations},suggestedColumn:gmx.column};gcal.vials.push(v);gcCalSave();gmx.message='Mixed vial prepared. All '+Object.keys(v.mix).length+' analytical solvents will enter the same column in one injection. Export this vial from the rack below.';return v}
function gcMixtureMethod(){const column=gmx.column;let m={...gcDefaults(),detectorType:gc.method.detectorType||'fid',column};if(column==='wax')m={...m,initial:50,hold:1,ramp:5,final:150,finalHold:3};else if(gmx.group==='alcohols')m={...m,ovenMode:'isothermal',initial:60,runtime:8};else if(gmx.group==='aromatics')m={...m,initial:80,final:180};gc.method=m;gc.ready=false;gc.flame=false;gc.finishedTemp=null;gcSave();gmx.prediction=null;gmx.message='Suggested '+GC_COLUMNS[column].name+' method applied to GC. Prediction uses these settings; instrument temperatures must be re-equilibrated.';}
function gcMixturePredict(){const r=gcMixtureRecipe(),input=GC_COMPOUNDS.filter(c=>r.mix[c.id]>0).map(c=>({...c,concentration:r.mix[c.id]})),sim=gcSimulate({...gc.method},input);gmx.prediction={method:sim.method,holdup:sim.holdup,efficiency:sim.efficiency,velocity:sim.velocity,components:sim.components.map(c=>({id:c.id,name:c.name,bp:c.bp,tr:c.tr,sigma:c.sigma,k:gcRetention(c,sim.method,sim.method.initial)})),warnings:sim.warnings};gmx.message='Predicted order below uses the same numerical model as the acquired chromatogram. It is not an experimental retention-time guarantee.';return gmx.prediction}
function gcMixturePrediction(){const p=gmx.prediction;if(!p)return '<p>Apply a column method, then predict the order before injection. Change the method to compare separations.</p>';const sorted=[...p.components].sort((a,b)=>(a.tr??Infinity)-(b.tr??Infinity));return `<p><b>Current method:</b> ${GC_COLUMNS[p.method.column].name} · ${p.method.ovenMode==='program'?p.method.initial+' → '+p.method.final+' °C at '+p.method.ramp+' °C/min':p.method.initial+' °C isothermal'} · ${p.method.gas||'helium'} ${p.method.flow} mL/min · ${p.method.length} m × ${p.method.id} mm × ${p.method.film} µm.<br>Model hold-up time ${gcFmt(p.holdup,3)} min · linear velocity ${gcFmt(p.velocity,1)} cm/s.</p><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Predicted order</th><th>Compound</th><th>Boiling point / °C</th><th>k at initial T</th><th>Model tR / min</th><th>Resolution to previous</th></tr></thead><tbody>${sorted.map((c,i)=>{const prev=sorted[i-1],rs=prev?.tr!==null&&prev?.tr!==undefined&&c.tr!==null?(c.tr-prev.tr)/(2*(c.sigma+prev.sigma)):null;return `<tr><td>${c.tr===null?'Not eluted':i+1}</td><td>${c.name}</td><td>${c.bp}</td><td>${gcFmt(c.k,3)}</td><td>${c.tr===null?'Beyond run':gcFmt(c.tr,3)}</td><td>${rs===null?'—':gcFmt(rs,2)+(rs<1.5?' · overlap risk':'')}</td></tr>`}).join('')}</tbody></table></div><p>${p.method.column==='wax'?'PEG/WAX adds strong polar and hydrogen-bonding selectivity; a lower boiling point does not guarantee earlier elution.':'On nonpolar phases volatility often dominates within a homologous family, while molecular structure and stationary-phase interactions can change selectivity.'} Neighbouring bands need sufficient selectivity and column efficiency; similar polarity does not guarantee baseline separation.</p>${p.warnings.map(w=>`<p class="gc-notice gc-warn">${w}</p>`).join('')}`}
function gcMixtureRackRow(v){return `<tr><td>${gcPrepEsc(gcVialLabel(v))}<br><small>separation mixture</small></td><td>${Object.keys(v.mix).length} analytical solvents</td><td colspan="2"><details><summary>Component concentrations</summary>${Object.entries(v.mix).map(([id,c])=>`${gcCalName(id)}: ${gcFmt(c,4)} mg/mL`).join('<br>')}</details></td><td>${gcPrepEsc(gcVialSolvent(v))} (diluent)</td><td>${gcFmt(v.preparation.totalAliquot,4)} combined aliquots → ${v.preparation.final} mL</td><td><button class="btn secondary small" data-gprep-export="${v.id}" ${gcLocked()||gseq.active?'disabled':''}>${v.exported?'Exported · add injection':'Export to GC'}</button></td></tr>`}
function gcMixturePanel(){if(gmx.prediction&&JSON.stringify(gmx.prediction.method)!==JSON.stringify(gc.method))gmx.prediction=null;const group=GC_MIX_GROUPS[gmx.group],locked=gcLocked()||gseq.active,disabled=locked?'disabled':'';return `${gcMixtureTabs()}<section class="panel gc-panel gprep"><div class="gc-titlebar"><div><span class="eyebrow">OPEN BENCH · ONE VIAL, MULTIPLE COMPOUNDS</span><h2>Mix solvents and investigate separation</h2></div><button class="btn secondary" data-gprep-action="instrument">Go to GC →</button></div><p>The selected solvents are the <b>analytical components</b>: every selected compound produces its own band and FID response. They share a polarity family, rather than identical polarity. A separate diluent makes the sample suitable for injection; its bulk peak is omitted.</p><div class="gcal-setup"><label class="gc-field">Polarity family<select data-gmx-select="group" ${disabled}>${Object.entries(GC_MIX_GROUPS).map(([id,g])=>`<option value="${id}" ${gmx.group===id?'selected':''}>${g.name}</option>`).join('')}</select></label><label class="gc-field">Preparation<select data-gmx-select="mode" ${disabled}><option value="neat" ${gmx.mode==='neat'?'selected':''}>Measured neat liquids / µL</option><option value="stock" ${gmx.mode==='stock'?'selected':''}>Stock solutions / mg/mL and mL</option></select></label><label class="gc-field">Vial label<input data-gmx-text="label" maxlength="60" value="${gcPrepEsc(gmx.label)}" placeholder="e.g. Alcohol mixture A" ${disabled}></label></div><div class="gc-two"><label class="gc-field">Final diluted volume / mL<input type="number" min="0.01" max="1000" step="any" data-gmx-number="final" value="${gmx.final}" ${disabled}></label><label class="gc-field">Separate diluent<select data-gmx-select="diluent" ${disabled}>${GC_SOLVENTS.map(s=>`<option value="${s.id}" ${gmx.diluent===s.id?'selected':''}>${s.name}</option>`).join('')}</select></label></div><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Include solvent</th><th>Boiling point / °C</th>${gmx.mode==='neat'?'<th>Density / g mL⁻¹ (approx.)</th><th>Measured addition / µL</th>':'<th>Stock / mg mL⁻¹</th><th>Aliquot / mL</th>'}</tr></thead><tbody>${group.ids.map(id=>{const c=GC_COMPOUNDS.find(c=>c.id===id),a=gmx.amounts[id];return `<tr><td><label class="gc-check"><input type="checkbox" data-gmx-component="${id}" ${gmx.selected.includes(id)?'checked':''} ${disabled}>${c.name}</label></td><td>${c.bp}</td>${gmx.mode==='neat'?`<td>${GC_MIX_DENSITY[id]}</td><td><input class="gmx-amount" type="number" step="any" min="0" aria-label="${c.name} neat volume in microlitres" data-gmx-amount="${id}" data-gmx-key="neat" value="${a.neat}" ${disabled}></td>`:`<td><input class="gmx-amount" type="number" step="any" min="0" aria-label="${c.name} stock concentration" data-gmx-amount="${id}" data-gmx-key="stock" value="${a.stock}" ${disabled}></td><td><input class="gmx-amount" type="number" step="any" min="0" aria-label="${c.name} aliquot volume" data-gmx-amount="${id}" data-gmx-key="aliquot" value="${a.aliquot}" ${disabled}></td>`}</tr>`}).join('')}</tbody></table></div><p>${gmx.mode==='neat'?'C component (mg/mL) = density (g/mL) × neat volume (µL) / final volume (mL). Approximate room-temperature densities are used; temperature, purity and volume contraction are not modelled.':'C component = C stock × V aliquot / V final. Assume the stock solutions use the selected compatible diluent.'} Dilute <b>to</b> the final volume after all additions. Each component must be ≤20 mg/mL.</p><div class="gc-actions"><label class="gc-field">Column for suggested method<select data-gmx-select="column" ${disabled}>${Object.entries(GC_COLUMNS).map(([id,c])=>`<option value="${id}" ${gmx.column===id?'selected':''}>${c.name}</option>`).join('')}</select></label><button class="btn secondary" data-gmx-action="method" ${disabled}>Apply suggested column method</button><button class="btn secondary" data-gmx-action="predict" ${disabled}>Predict separation</button><button class="btn" data-gmx-action="prepare" ${disabled}>Prepare mixed vial</button></div><div class="gc-notice" role="status">${gcPrepEsc(gmx.message)}</div><details class="gc-detail" ${gmx.prediction?'open':''}><summary>Predicted elution order &amp; separation</summary><div id="gcMixturePrediction">${gcMixturePrediction()}</div></details>${gcSeparationGuide()}<div class="gc-titlebar"><h3>Prepared vial rack</h3><button class="btn secondary small" data-gprep-action="export-all" ${locked||!gcal.vials.length?'disabled':''}>Export all to GC</button></div>${gcPreparedRack()}</section>`}
function gcSeparationGuide(){return `<details class="gc-detail"><summary>What determines elution order and resolution?</summary><div class="gc-table-wrap"><table class="gc-table"><thead><tr><th>Factor</th><th>Effect represented in this simulator</th></tr></thead><tbody><tr><td>Volatility &amp; chemical structure</td><td>Compound-specific retention anchors and temperature dependence. Boiling point alone is insufficient.</td></tr><tr><td>Stationary phase</td><td>Dispersive interactions on PDMS, extra aromatic selectivity with phenyl, and polar / hydrogen-bonding selectivity on WAX.</td></tr><tr><td>Oven temperature &amp; ramp</td><td>Migration is integrated as temperature changes. Hotter / faster methods shorten retention and may compress neighbouring peaks.</td></tr><tr><td>Length, internal diameter &amp; film</td><td>Column volume, phase-volume ratio, retention and efficiency change. Thicker films also increase mass-transfer broadening.</td></tr><tr><td>Carrier gas &amp; flow</td><td>Flow sets hold-up time; gas-dependent diffusion and mass-transfer terms change efficiency. Gas identity alone does not change equilibrium selectivity.</td></tr><tr><td>Injector, loading &amp; injection time</td><td>Transfer loss and initial band width affect area and resolution. Loading above model capacity broadens bands; it is not a validated nonlinear adsorption model.</td></tr><tr><td>FID conditions</td><td>Carbon-sensitive response and detection change signal, not equilibrium elution order.</td></tr></tbody></table></div><p><b>Accuracy boundary:</b> retention times are model predictions, not experimentally validated values. Real separation also depends on exact phase chemistry, pressure/compressibility, column activity and ageing, matrix/solvent effects, dead volumes, leaks and instrument condition. Those factors are not all quantified here. Use experimentally measured standards to establish real elution order; FID alone cannot prove identity.</p><p><b>Documented close-pair example:</b> NIST lists Kovats indices of 935 for 2-propanol, 944 for ethanol and 1046 for 1-propanol on Supelcowax-10 at 60 °C (60 m × 0.75 mm, nitrogen; Castello, Vezzani et al., 1991). This supports column-dependent alcohol selectivity and a close ethanol / 2-propanol pair. These are indices, not retention times, and that reference column is different from this simulated column.</p><p>Approximate density references: <a href="https://www.cdc.gov/niosh/docs/2003-154/pdfs/2000.pdf" target="_blank" rel="noopener">NIOSH methanol method 2000</a>, <a href="https://www.cdc.gov/niosh/docs/2003-154/pdfs/1500.pdf" target="_blank" rel="noopener">NIOSH hydrocarbons method 1500</a>, <a href="https://physics.nist.gov/cgi-bin/Star/compos.pl?matno=240" target="_blank" rel="noopener">NIST 1-propanol density</a>. Preparation uses approximate room-temperature values, not a certified density or purity assay.</p><p>Separation references: <a href="https://www.phenomenex.com/resources/knowledge-center/gc-knowledge-center/good-column-selection-polarity-vs-selectivity" target="_blank" rel="noopener">Phenomenex: polarity and selectivity</a>; <a href="https://www.ssi.shimadzu.com/service-support/faq/gas-chromatography/columns/index.html" target="_blank" rel="noopener">Shimadzu: column selection</a>; <a href="https://www.agilent.com/cs/library/usermanuals/public/G1176-90000_035287.pdf" target="_blank" rel="noopener">Agilent: fundamentals of GC</a>; <a href="https://webbook.nist.gov/cgi/cbook.cgi?ID=C64175&amp;Mask=2000" target="_blank" rel="noopener">NIST ethanol</a>, <a href="https://webbook.nist.gov/cgi/cbook.cgi?ID=C67630&amp;Mask=2000" target="_blank" rel="noopener">2-propanol</a>, <a href="https://webbook.nist.gov/cgi/cbook.cgi?ID=C71238&amp;Mask=2000" target="_blank" rel="noopener">1-propanol</a>.</p></details>`}
function gcMixtureInvalidate(){gmx.prediction=null;const el=document.getElementById('gcMixturePrediction');if(el)el.textContent='Inputs changed. Select Predict separation to update the prediction.';gcMixtureSave()}
document.addEventListener('input',e=>{if(gcLocked()||gseq.active)return;const t=e.target;if(t.dataset.gmxAmount){gmx.amounts[t.dataset.gmxAmount][t.dataset.gmxKey]=Number(t.value);gcMixtureInvalidate()}else if(t.dataset.gmxNumber){gmx[t.dataset.gmxNumber]=Number(t.value);gcMixtureInvalidate()}else if(t.dataset.gmxText){gmx[t.dataset.gmxText]=t.value;gcMixtureSave()}});
document.addEventListener('change',e=>{if(gcLocked()||gseq.active)return;const t=e.target;if(t.dataset.gmxComponent){gmx.selected=t.checked?[...new Set([...gmx.selected,t.dataset.gmxComponent])]:gmx.selected.filter(id=>id!==t.dataset.gmxComponent);gcMixtureInvalidate();gcCalRefresh()}if(t.dataset.gmxSelect){gmx[t.dataset.gmxSelect]=t.value;if(t.dataset.gmxSelect==='group'){const g=GC_MIX_GROUPS[gmx.group];gmx.selected=[...g.ids];gmx.diluent=g.diluent;gmx.column=g.column;}gcMixtureInvalidate();gcCalRefresh()}});
document.addEventListener('click',e=>{const tab=e.target.closest('[data-gmx-tab]');if(tab){gmx.tab=tab.dataset.gmxTab;gcMixtureSave();gcCalRefresh();return}if(gcLocked()||gseq.active)return;const a=e.target.closest('[data-gmx-action]')?.dataset.gmxAction;if(!a)return;try{if(a==='method')gcMixtureMethod();if(a==='predict')gcMixturePredict();if(a==='prepare')gcMixturePrepare();}catch(err){gmx.message=err.message}gcMixtureSave();gcCalRefresh()});
